<?= $this->extend('resources/layout') ?><?= $this->section('styles') ?><link rel="stylesheet" href="<?= base_url('css/borrower-workspace.css?v=1') ?>"><?= $this->endSection() ?><?= $this->section('content') ?><script src="<?= base_url('js/admin-payment-copy.js?v=2') ?>" defer></script>
<p class="student-note">All transaction dates are displayed in Asia/Manila.</p><div class="table-wrap"><table class="student-payment-table"><thead><tr><th>Reservation No.</th><th>Transaction Ref.</th><th>Payment Method</th><th>Amount</th><th>Transaction Date</th><th>Payment Status</th><th>Receipt</th></tr></thead><tbody><?php foreach($payments as $payment): $ref=(string)$payment['transaction_reference'];$short=mb_strlen($ref)>15?mb_substr($ref,0,8).'…'.mb_substr($ref,-4):$ref;$date=(new DateTimeImmutable($payment['created_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone(config('Booking')->timezone));$method=['gcash'=>'GCash','card'=>'Card','bank_transfer'=>'Bank Transfer'][$payment['payment_method']]??$payment['payment_method']; ?><tr><td><a href="<?= site_url('borrower/reservations/'.$payment['reservation_id']) ?>">#<?= (int)$payment['reservation_id'] ?></a></td><td><div class="student-reference"><span title="<?= esc($ref,'attr') ?>"><?= esc($short) ?></span><button type="button" class="copy-reference" data-reference="<?= esc($ref,'attr') ?>" aria-label="Copy full transaction reference" title="Copy full reference"><span class="material-symbols-outlined" aria-hidden="true">content_copy</span></button><span class="copy-feedback" role="status" aria-live="polite"></span></div></td><td><?= esc($method) ?></td><td><?= $payment['currency']==='PHP'?'₱':esc($payment['currency']).' ' ?><?= esc(number_format((float)$payment['amount'],2)) ?></td><td><?= esc($date->format('M j, Y')) ?><small><?= esc($date->format('g:i A')) ?></small></td><td><span class="status-badge <?= esc($payment['payment_status'],'attr') ?>"><?= esc(ucfirst($payment['payment_status'])) ?></span></td><td><?php if($payment['payment_status']!=='pending'): ?><a href="<?= site_url('borrower/payments/'.$payment['id'].'/receipt') ?>"><?= $payment['payment_status'] === 'paid' ? 'Receipt' : 'Transaction details' ?></a><?php else: ?>—<?php endif ?></td></tr><?php endforeach ?><?php if(!$payments): ?><tr><td colspan="7">No payment transactions yet.</td></tr><?php endif ?></tbody></table></div><?= $pager ?>
<?= $this->endSection() ?>
